/* ICRC is the only little-endian multibyte field on the wire. */
static uint32_t load32le(const uint8_t *p) {
    return ((uint32_t)p[3] << 24) | ((uint32_t)p[2] << 16) | ((uint32_t)p[1] << 8) |
           p[0];
}

bool epic_wire_validate(const uint8_t *frame, size_t frame_len, size_t words,
                        epic_wire_t *out) {
    const size_t ip_off = EPIC_ETH_LEN;

    out->is_ack = false;
    out->psn = 0;
    out->qpn = 0;
    out->payload = NULL;
    out->payload_len = 0;

    if (!frame || !out) {
        return false;
    }
    /* Ethernet: IPv4 only, no FCS or padding is present. */
    if (frame_len < EPIC_ETH_LEN + EPIC_IP_LEN + EPIC_UDP_LEN + EPIC_BTH_LEN +
                       EPIC_ICRC_LEN) {
        return false;
    }
    if (load16(frame + 12) != ETHERTYPE_IPV4) {
        return false;
    }
    const uint8_t *ip = frame + ip_off;
    if (ip[0] != 0x45) {                      /* version 4, IHL 20, no options */
        return false;
    }
    size_t ip_len = load16(ip + 2);
    if (ip_len < EPIC_IP_LEN + EPIC_UDP_LEN + EPIC_BTH_LEN + EPIC_ICRC_LEN ||
        frame_len != EPIC_ETH_LEN + ip_len) { /* exact length agreement */
        return false;
    }
    if (ip[9] != 17) {                        /* protocol UDP */
        return false;
    }
    uint16_t flags = (uint16_t)((ip[6] << 8) | ip[7]);
    if (flags != 0x0000 && flags != 0x4000) { /* DF only, never fragmented */
        return false;
    }
    uint8_t hdr[EPIC_IP_LEN];
    memcpy(hdr, ip, EPIC_IP_LEN);
    hdr[10] = 0;
    hdr[11] = 0;
    if (load16(ip + 10) != ntohs(epic_ipv4_checksum(hdr, EPIC_IP_LEN))) {
        return false;
    }
    const uint8_t *udp = ip + EPIC_IP_LEN;
    size_t udp_len = load16(udp + 4);
    if (udp_len != ip_len - EPIC_IP_LEN) {
        return false;
    }
    if (load16(udp + 0) != EPIC_ROCE_UDP_PORT ||
        load16(udp + 2) != EPIC_ROCE_UDP_PORT || load16(udp + 6) != 0) {
        return false;
    }
    if (udp_len < EPIC_UDP_LEN + EPIC_BTH_LEN + EPIC_ICRC_LEN) {
        return false;
    }
    const uint8_t *bth = udp + EPIC_UDP_LEN;
    uint8_t opcode = bth[0];
    if (opcode != ROCE_OPCODE_DATA && opcode != ROCE_OPCODE_ACK) {
        return false;
    }
    if (bth[1] != 0) { /* flags/padding byte zero */
        return false;
    }
    if (load16(bth + 2) != 0xffff) {
        return false;
    }
    uint32_t qpn = load32(bth + 4);
    if ((qpn >> 24) & 0xffu) {
        return false;
    }
    uint32_t apsn = load32(bth + 8);
    uint32_t psn = apsn & EPIC_PSN_MASK;
